from pathlib import Path
out=Path('survey/out');root=Path('docs/superpowers/specs');stem='2026-10-02-emergent-polarity'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
before=json.loads((root/(stem+'-pre-sequential-findings.json')).read_text());prefix=[]
with (out/'polarity-final-findings.json').open() as f:
 for line in f:
  if line.startswith('  "raw_records": ['):
   prefix.append('  "raw_records": []\n}\n');break
  prefix.append(line)
 else:raise ValueError('Missing final raw_records field in registered export')
after=json.loads(''.join(prefix));assembly=json.loads((out/'polarity-final-assembly-receipt.json').read_text());ids={x['id'] for x in assembly['per_arm']}
