unaffected_nonselection=[aid for aid,row in before_rows.items() if row['family']!='selection'];assert all(before_rows[aid]==after_rows[aid] for aid in unaffected_nonselection)
assert before['stoermer']==after['stoermer']
changes=[{'id':aid,'before':before_rows[aid],'after':after_rows[aid]} for aid in sorted(before_rows) if before_rows[aid]!=after_rows[aid]]
arm_before={x['id']:x for x in before['arms']};arm_after={x['id']:x for x in after['arms']}
assert all(arm_before[a]==arm_after[a] for a in arm_before if a not in ids)
result={'schema_version':1,'compared_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'command':'python3 survey/out/polarity-compare-verdicts.py','comparison_script_sha256':sha(__file__),'comparison_script_source':Path(__file__).read_text(),'registered_analysis_code_sha256':sha('survey/polarity/analysis.py'),'original_full_findings_sha256':sha(out/'polarity-telemetry-findings.json'),'final_findings_sha256':sha(out/'polarity-final-findings.json'),'original_full_sessions_sha256':sha(out/'polarity-telemetry-sessions.jsonl'),'final_sessions_sha256':sha(out/'polarity-final-sessions.jsonl'),'all_registered_rows_compared':len(before_rows),'unchanged_registered_rows':len(before_rows)-len(changes),'all_nonselection_registered_rows_unchanged':True,'unchanged_nonselection_row_count':len(unaffected_nonselection),'all_stoermer_coordinates_unchanged':True,'changed_registered_rows':changes,'verdict_changes':[{'id':a,'before':before_rows[a]['verdict'],'after':after_rows[a]['verdict']} for a in sorted(before_rows) if before_rows[a]['verdict']!=after_rows[a]['verdict']],'affected_arm_before_after':[{'id':a,'before':arm_before[a],'after':arm_after[a]} for a in sorted(ids)],'unchanged_nonsequential_arm_summaries':len(arm_before)-len(ids),'interpretation':'All judges recomputed with unchanged rules/draw count/base seed on the complete assembled dataset. Restoring unavailable sequential selection rows can change registered Holm corrections and the seeded draw schedule for later selection rows; every changed registered result/verdict is retained here.'}
(root/(stem+'-sequential-before-after.json')).write_text(json.dumps(result,indent=2,sort_keys=True,allow_nan=False)+'\n')
summary=before
(root/(stem+'-pre-sequential-findings.json')).write_text(json.dumps(summary,indent=2,sort_keys=True,allow_nan=False)+'\n');(root/(stem+'-pre-sequential-findings.md')).write_bytes((out/'polarity-telemetry-findings.md').read_bytes())
print(json.dumps({k:v for k,v in result.items() if k not in ['comparison_script_source','changed_registered_rows','affected_arm_before_after']},indent=2))
